import java.io.IOException;
import java.util.*;

public class Test {
    int readInt() {
        int number = 0;
        boolean isNegative = false;
        try {
            boolean started = false;
            for (int ch = 0; (ch = System.in.read()) != -1; ) {
                if (ch == '-') {
                    started = true;
                    isNegative = true;
                    continue;
                } else if (ch >= '0' && ch <= '9') {
                    started = true;
                    number = number * 10 + ch - '0';
                } else if (started) break;
            }
        } catch (IOException e) {
        }
        return isNegative ? -number : number;
    }

    int R, C;
    Scanner sc = new Scanner(System.in);
    long[][] binom = new long[64][64];
    long minDifference = Long.MAX_VALUE;

    void searchPath(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (minDifference <= 1 || diff - binom[v1][R]*binom[v2][R] >= minDifference) return;
        if (v1 == R - 1 && v2 == R - 1) {
            if (diff < minDifference) minDifference = diff;
            return;
        }
        if (v1 >= R) {
            long deltaX = binom[v1][R] - binom[v1-1][R], deltaY = binom[v2][R];
            searchPath(x, y + deltaX*deltaY, v1 - 1, v2);
        }
        if (v2 >= R) {
            long deltaX = binom[v1][R], deltaY = binom[v2][R] - binom[v2-1][R];
            searchPath(x + deltaX*deltaY, y, v1, v2 - 1);
        }
    }

    int[] countA = new int[64], countB = new int[64];
    Map<Long, Long> cacheMap = new TreeMap<>();
    char[] sequenceChars;

    long solveRec(long x, long y, int v1, int v2) {
        long key = x*10000 + v1*100 + v2;
        Long cachedVal = cacheMap.get(key);
        if (cachedVal != null) return cachedVal;
        long result = 0L;
        long d = Math.abs(x - y);
        if (d - binom[v1][R]*binom[v2][R] > minDifference) {
            cacheMap.put(key, result);
            return result;
        }
        if (v1 < R || v2 < R) {
            int sumIdx = v1 + v2;
            if (v1 >= countA[sumIdx] && v2 >= countB[sumIdx]) {
                v1 -= countA[sumIdx];
                v2 -= countB[sumIdx];
                result = binom[v1+v2][v1];
                cacheMap.put(key, result);
                return result;
            }
            cacheMap.put(key, result);
            return result;
        }
        char c = sequenceChars[v1 + v2 - 1];
        if (c != 'B') {
            long c1 = binom[v1][R] - binom[v1 - 1][R], s2 = binom[v2][R];
            result += solveRec(x, y + c1*s2, v1 - 1, v2);
        }
        if (c != 'A') {
            long s1 = binom[v1][R], c2 = binom[v2][R] - binom[v2-1][R];
            result += solveRec( x + s1*c2, y, v1, v2 - 1);
        }
        cacheMap.put(key, result);
        return result;
    }

    void runProgram() {
        R = readInt(); C = readInt(); sc.nextLine();
        sequenceChars = sc.nextLine().toCharArray();
        for (int i = 0; i <= 2*(R + C); i++)
            for (int j = 0; j <= 2*(R + C); j++) {
                if (j == 0) binom[i][j] = 1;
                else if (i == 0) binom[i][j] = 0;
                else binom[i][j] = binom[i-1][j-1] + binom[i-1][j];
            }
        int v1 = R + C, v2 = R + C;
        long xCoord = 0, yCoord = 0;
        while (v1 >= R && v2 >= R) {
            if (xCoord > yCoord) {
                long c1 = binom[v1][R] - binom[v1 - 1][R], s2 = binom[v2][R];
                yCoord += c1 * s2;
                v1--;
            } else {
                long s1 = binom[v1][R], c2 = binom[v2][R] - binom[v2-1][R];
                xCoord += s1 * c2;
                v2--;
            }
        }
        minDifference = Math.abs(xCoord - yCoord);
        searchPath(0, 0, R + C, R + C);
        for (int i = 0; i < 2*(R+C); i++) {
            countA[i + 1] = countA[i] + (sequenceChars[i] == 'A' ? 1 : 0);
            countB[i + 1] = countB[i] + (sequenceChars[i] == 'B' ? 1 : 0);
        }
        long answer = solveRec(0, 0, R + C, R + C);
        System.out.println(answer);
    }

    public static void main(String[] args) {
        new Test().runProgram();
    }
}
